components.css:
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: hsl(192 88% 34%);
  color: hsl(210 40% 98%);
  border-radius: 1rem;
  padding: 12px 24px;
  font-size: 0.875rem;
  font-weight: 500;
  border: none;
  cursor: pointer;
  box-shadow: 0 10px 30px -18px hsl(224 42% 10% / 0.22);
  transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}
.ds-btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 30px 80px -28px hsl(224 42% 10% / 0.28);
}
.ds-btn-primary:focus-visible {
  outline: 2px solid hsl(192 88% 34%);
  outline-offset: 2px;
}
.ds-btn-primary:active {
  transform: translateY(0);
}

.ds-btn-outline {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: hsl(210 33% 98% / 0.6);
  backdrop-filter: blur(14px);
  color: hsl(224 42% 10%);
  border-radius: 1rem;
  padding: 12px 24px;
  font-size: 0.875rem;
  font-weight: 500;
  border: 1px solid hsl(216 24% 86%);
  cursor: pointer;
  transition: background 0.3s cubic-bezier(0.22, 1, 0.36, 1), border-color 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}
.ds-btn-outline:hover {
  background: hsl(210 29% 93%);
}
.ds-btn-outline:focus-visible {
  outline: 2px solid hsl(192 88% 34%);
  outline-offset: 2px;
}

.ds-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  background: hsl(210 33% 98% / 0.6);
  backdrop-filter: blur(14px);
  color: hsl(220 14% 42%);
  border-radius: 2rem;
  padding: 4px 12px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.75rem;
  letter-spacing: 0.18em;
  border: 1px solid hsl(216 24% 86% / 0.7);
}
.ds-chip--dark {
  background: hsl(223 24% 15% / 0.6);
  color: hsl(215 18% 72%);
  border-color: hsl(223 20% 18% / 0.7);
}

.ds-card {
  background: hsl(0 0% 100%);
  color: hsl(224 42% 10%);
  border-radius: 1.5rem;
  border: 1px solid hsl(216 24% 86%);
  padding: 1.25rem;
  transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}
.ds-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 30px -18px hsl(224 42% 10% / 0.22);
}
.ds-card__icon {
  display: grid;
  place-items: center;
  width: 3rem;
  height: 3rem;
  border-radius: 0.75rem;
  background: hsl(210 29% 93%);
  color: hsl(192 88% 34%);
}
.ds-card:hover .ds-card__icon {
  background: hsl(192 88% 34%);
  color: hsl(210 40% 98%);
}
.ds-card__title {
  font-size: 0.875rem;
  font-weight: 500;
  color: hsl(224 42% 10%);
}
.ds-card__desc {
  margin-top: 0.75rem;
  font-size: 0.875rem;
  color: hsl(220 14% 42%);
}
.ds-card--dark {
  background: hsl(224 36% 10%);
  color: hsl(210 40% 98%);
  border-color: hsl(223 20% 18%);
}
.ds-card--dark .ds-card__icon {
  background: hsl(223 24% 15%);
}
.ds-card--dark:hover .ds-card__icon {
  background: hsl(191 88% 52%);
  color: hsl(224 42% 10%);
}
.ds-card--dark .ds-card__title { color: hsl(210 40% 98%); }
.ds-card--dark .ds-card__desc { color: hsl(215 18% 72%); }

.ds-nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 50;
  padding: 1.25rem;
  transition: padding 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}
.ds-nav.scrolled {
  padding: 0.75rem;
}
.ds-nav-inner {
  max-width: 1152px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  border-radius: 2rem;
  padding: 0.5rem;
  transition: background 0.5s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}
.ds-nav.scrolled .ds-nav-inner {
  background: hsl(210 33% 98% / 0.6);
  backdrop-filter: blur(14px);
  box-shadow: 0 10px 30px -18px hsl(224 42% 10% / 0.22);
}
.ds-nav-brand {
  font-family: 'Space Grotesk', system-ui, sans-serif;
  font-size: 1.25rem;
  font-weight: 600;
  letter-spacing: -0.04em;
  color: hsl(224 42% 10%);
  text-decoration: none;
}
.ds-nav-dot {
  color: hsl(192 88% 34%);
}
.ds-nav-links {
  display: flex;
  gap: 0.25rem;
  list-style: none;
  margin: 0;
  padding: 0;
}
.ds-nav-links a {
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
  color: hsl(220 14% 42%);
  border-radius: 2rem;
  text-decoration: none;
  transition: color 0.2s;
}
.ds-nav-links a:hover {
  color: hsl(224 42% 10%);
}
.ds-nav-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
@media (max-width: 767px) {
  .ds-nav-links { display: none; }
}

.ds-project {
  background: hsl(0 0% 100%);
  color: hsl(224 42% 10%);
  border-radius: 2rem;
  border: 1px solid hsl(216 24% 86%);
  overflow: hidden;
  transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}
.ds-project:hover {
  transform: translateY(-4px);
  box-shadow: 0 30px 80px -28px hsl(224 42% 10% / 0.28);
}
.ds-project-media {
  position: relative;
  aspect-ratio: 16 / 10;
  overflow: hidden;
  border-bottom: 1px solid hsl(216 24% 86%);
}
.ds-project-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: top;
  transition: transform 0.7s cubic-bezier(0.22, 1, 0.36, 1);
}
.ds-project:hover .ds-project-media img {
  transform: scale(1.03);
}
.ds-project-tags {
  position: absolute;
  bottom: 1rem;
  left: 1rem;
  right: 1rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  background: linear-gradient(to top, hsl(0 0% 100%) 0%, hsl(0 0% 100% / 0.88) 60%, transparent 100%);
  padding: 1rem;
  padding-top: 2.5rem;
}
.ds-project-tags span {
  display: inline-block;
  border-radius: 2rem;
  background: hsl(210 33% 98% / 0.85);
  backdrop-filter: blur(14px);
  color: hsl(220 14% 42%);
  padding: 4px 12px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.75rem;
  border: 1px solid hsl(216 24% 86% / 0.8);
}
.ds-project-body {
  padding: 1.5rem;
}
.ds-project-category {
  font-size: 0.75rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: hsl(220 14% 42%);
}
.ds-project-title {
  margin-top: 0.5rem;
  font-family: 'Space Grotesk', system-ui, sans-serif;
  font-size: 1.5rem;
  font-weight: 400;
  color: hsl(224 42% 10%);
}
.ds-project-desc {
  margin-top: 0.5rem;
  font-size: 0.875rem;
  line-height: 1.6;
  color: hsl(220 14% 42%);
}
.ds-project-cta {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  margin-top: 1.25rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: hsl(192 88% 34%);
  text-decoration: none;
  transition: gap 0.2s;
}
.ds-project-cta:hover { gap: 0.625rem; }
.ds-project--dark {
  background: hsl(224 36% 10%);
  color: hsl(210 40% 98%);
  border-color: hsl(223 20% 18%);
}
.ds-project--dark .ds-project-tags {
  background: linear-gradient(to top, hsl(224 36% 10%) 0%, hsl(224 36% 10% / 0.88) 60%, transparent 100%);
}
.ds-project--dark .ds-project-tags span {
  background: hsl(210 40% 98% / 0.85);
  color: hsl(220 14% 42%);
  border-color: hsl(223 20% 18% / 0.8);
}
.ds-project--dark .ds-project-category { color: hsl(215 18% 72%); }
.ds-project--dark .ds-project-title { color: hsl(210 40% 98%); }
.ds-project--dark .ds-project-desc { color: hsl(215 18% 72%); }

.ds-skill {
  background: hsl(0 0% 100%);
  color: hsl(224 42% 10%);
  border-radius: 1.5rem;
  border: 1px solid hsl(216 24% 86%);
  padding: 1.25rem;
  transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1), border-color 0.3s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}
.ds-skill:hover {
  transform: translateY(-4px);
  border-color: hsl(192 88% 34% / 0.3);
  box-shadow: 0 10px 30px -18px hsl(224 42% 10% / 0.22);
}
.ds-skill-icon {
  display: grid;
  place-items: center;
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 0.75rem;
  background: hsl(210 29% 93%);
  color: hsl(192 88% 34%);
  transition: background 0.3s cubic-bezier(0.22, 1, 0.36, 1), color 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}
.ds-skill:hover .ds-skill-icon {
  background: hsl(192 88% 34%);
  color: hsl(210 40% 98%);
}
.ds-skill-label {
  margin-top: 1rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: hsl(224 42% 10%);
}
.ds-skill--dark {
  background: hsl(224 36% 10%);
  color: hsl(210 40% 98%);
  border-color: hsl(223 20% 18%);
}
.ds-skill--dark:hover {
  border-color: hsl(191 88% 52% / 0.3);
}
.ds-skill--dark .ds-skill-icon {
  background: hsl(223 24% 15%);
}
.ds-skill--dark:hover .ds-skill-icon {
  background: hsl(191 88% 52%);
  color: hsl(224 42% 10%);
}
.ds-skill--dark .ds-skill-label { color: hsl(210 40% 98%); }

.ds-contact-card {
  display: flex;
  align-items: center;
  gap: 1rem;
  border-radius: 1.5rem;
  background: hsl(255 255 255 / 0.08);
  backdrop-filter: blur(14px);
  padding: 1.25rem;
  text-decoration: none;
  border: 1px solid hsl(255 255 255 / 0.15);
  color: hsl(255 255 255);
  transition: background 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}
.ds-contact-card:hover {
  background: hsl(255 255 255 / 0.15);
}
.ds-contact-icon {
  display: grid;
  place-items: center;
  width: 3rem;
  height: 3rem;
  border-radius: 0.75rem;
  background: hsl(255 255 255 / 0.15);
}
.ds-contact-label {
  font-size: 0.75rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: hsl(255 255 255 / 0.6);
}
.ds-contact-value {
  margin-top: 0.25rem;
  font-size: 1rem;
  font-weight: 500;
  color: hsl(255 255 255);
}
.ds-contact-arrow {
  margin-left: auto;
  font-size: 1.25rem;
  color: hsl(255 255 255 / 0.7);
  transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}
.ds-contact-card:hover .ds-contact-arrow {
  transform: translate(2px, -2px);
  color: hsl(255 255 255);
}
